API Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the API Gateway container

Container_Boundary(api_gateway, "API Gateway") {
    Component(AWS_WAF, "AWS WAF", "AWS Managed Service", "Provides DDoS protection, rate-limiting, and ingress filtering at the edge.")
    Component(HTTP_API_Router, "HTTP API Router", "AWS API Gateway HTTP API", "Handles TLS termination and routes incoming payment authorization traffic.")
}

Rel(AWS_WAF, HTTP_API_Router, "Forwards filtered traffic", "HTTPS")

@enduml

Case Management Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(case_management_container, "Case Management Container") {
    Component(CaseManagementAPI, "Case Management API", "Node.js / Python (FastAPI)", "Routes analyst and reporting traffic and handles business logic for case reviews.")
    Component(DataAccessLayer, "Data Access Layer", "AWS SDK", "Reads and writes case data, audit logs, and model metadata to Amazon DynamoDB.")
    Component(EventHandler, "Event Handler", "AWS SDK / SQS", "Handles dead-letter queues for failed asynchronous events and consumes event updates.")
}

Rel(CaseManagementAPI, DataAccessLayer, "Reads/writes case data, audit logs, and model metadata", "Amazon DynamoDB via AWS SDK")
Rel(EventHandler, DataAccessLayer, "Consumes asynchronous event updates", "Amazon DynamoDB Streams")
Rel(CaseManagementAPI, EventHandler, "Handles dead-letter queues for failed asynchronous events", "AWS SDK")

@enduml

Event & Compliance Infrastructure.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Event & Compliance Infrastructure container

Container_Boundary(event_compliance_infrastructure, "Event & Compliance Infrastructure") {
    Component(Amazon_EventBridge_SNS, "Amazon EventBridge / SNS", "AWS EventBridge and Amazon SNS", "Handles asynchronous event decoupling and distribution for system-wide telemetry and alerts.")
    Component(Go_based_Audit_Logger, "Go-based Audit Logger", "Go", "Generates and exports tamper-evident audit logs and tracking events.")
    Component(Compliance_Vault_S3_Writer, "Compliance Vault S3 Writer", "AWS S3 with S3 Object Lock", "Writes and secures compliance data to S3 with Object Lock for 7-year auditability.")
    Component(Alerting_Dead_Letter_Monitor, "Alerting & Dead-Letter Monitor", "AWS SQS and Dead-Letter Queues", "Manages backpressure and monitors failures, exporting alerts asynchronously.")
}

Rel(Go_based_Audit_Logger, Compliance_Vault_S3_Writer, "Exports tamper-evident audit logs", "")
Rel(Alerting_Dead_Letter_Monitor, Amazon_EventBridge_SNS, "Sends failure alerts asynchronously", "")

@enduml
